package app.space.notes.runtime;
import android.media.MediaPlayer;
import android.os.*;
import android.widget.*;
import android.view.Gravity;
import java.io.File;
import java.util.Locale;
/** Single-recording transport. Preparing, paused, ended and detached states release safely. */
final class VoicePlaybackCard extends LinearLayout {
 private final NotesDesign d;private final File audio;private final Runnable exclusive;private final java.util.function.Consumer<String> message;private final Button play;private final SeekBar progress;private final TextView time;private final Handler handler=new Handler(Looper.getMainLooper());
 private MediaPlayer player;private boolean prepared,disposed,seeking;private int duration;
 private final Runnable tick=new Runnable(){public void run(){if(player==null || !prepared || disposed)return;try{if(!seeking)progress.setProgress(player.getCurrentPosition());showTime(player.getCurrentPosition());if(player.isPlaying())handler.postDelayed(this,250);}catch(IllegalStateException gone){release();}}};
 VoicePlaybackCard(NotesDesign d,File audio,String state,String text,int duration,Runnable exclusive,java.util.function.Consumer<String> message,Runnable export,Runnable retry,Runnable open){super(d.context);this.d=d;this.audio=audio;this.duration=duration;this.exclusive=exclusive;this.message=message;setOrientation(VERTICAL);setPadding(d.dp(14),d.dp(14),d.dp(14),d.dp(12));android.graphics.drawable.GradientDrawable bg=d.shape(d.surface,18);bg.setStroke(d.dp(1),d.outline);setBackground(bg);setElevation(d.dp(1));LayoutParams margins=new LayoutParams(-1,-2);margins.setMargins(0,d.dp(6),0,d.dp(10));setLayoutParams(margins);
  addView(d.label(java.text.DateFormat.getDateTimeInstance().format(new java.util.Date(audio.lastModified())),16,d.ink));String status=state.equals("DONE")?"Transcript ready":state.toLowerCase(Locale.ROOT).contains("transcrib")?"Transcribing…":state.toLowerCase(Locale.ROOT).contains("fail")?"Transcript unavailable · retry":"Recording saved";TextView hint=d.label(status,13,d.muted);hint.setPadding(0,d.dp(6),0,d.dp(10));addView(hint);if(!text.isEmpty()){TextView words=d.label(text.length()>1000?text.substring(0,1000)+"…":text,17,d.ink);words.setTextIsSelectable(true);addView(words);}
  LinearLayout row=new LinearLayout(getContext());row.setGravity(Gravity.CENTER_VERTICAL);play=d.icon("Play","play",this::toggle);row.addView(play,new LayoutParams(d.dp(48),d.dp(48)));progress=new SeekBar(getContext());progress.setContentDescription("Recording playback position");progress.setEnabled(false);progress.setMax(Math.max(1,duration));row.addView(progress,new LayoutParams(0,d.dp(48),1));row.addView(d.icon("Stop playback","stop",this::stop),new LayoutParams(d.dp(48),d.dp(48)));addView(row);time=d.label("",12,d.muted);time.setGravity(Gravity.END);addView(time);showTime(0);
  progress.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar bar){seeking=true;}public void onProgressChanged(SeekBar bar,int value,boolean user){if(user && player!=null && prepared){player.seekTo(value);showTime(value);}}public void onStopTrackingTouch(SeekBar bar){seeking=false;handler.removeCallbacks(tick);tick.run();}});
  LinearLayout actions=new LinearLayout(getContext());actions.addView(d.icon("Export recording","export",export));actions.addView(d.icon("Retry transcript","retry",retry));actions.addView(d.icon("Open note","note",open));addView(actions);
 }
 private static String clock(int ms){return String.format(Locale.ROOT,"%d:%02d",ms/60000,(ms/1000)%60);}
 private void showTime(int position){time.setText(clock(position)+" / "+(duration>0?clock(duration):"—"));}
 private void playing(boolean value){String name=value?"Pause":"Play";play.setContentDescription(name);play.setTooltipText(name);NotesIcon icon=new NotesIcon(value?"pause":"play",d.ink);icon.setBounds(0,0,d.dp(24),d.dp(24));play.setCompoundDrawables(null,icon,null,null);}
 private void toggle(){if(disposed)return;if(player!=null && prepared){if(player.isPlaying())pause();else{exclusive.run();player.start();playing(true);tick.run();}return;}if(player!=null)return;exclusive.run();try{player=new MediaPlayer();player.setAudioAttributes(new android.media.AudioAttributes.Builder().setUsage(android.media.AudioAttributes.USAGE_MEDIA).setContentType(android.media.AudioAttributes.CONTENT_TYPE_SPEECH).build());player.setDataSource(audio.getPath());play.setEnabled(false);player.setOnPreparedListener(p->{if(disposed || p!=player){p.release();return;}exclusive.run();prepared=true;duration=p.getDuration();progress.setMax(Math.max(1,duration));progress.setEnabled(true);play.setEnabled(true);p.start();playing(true);tick.run();});player.setOnCompletionListener(p->{handler.removeCallbacks(tick);p.seekTo(0);progress.setProgress(0);showTime(0);playing(false);});player.setOnErrorListener((p,what,extra)->{release();message.accept("Could not play the recording. The original is retained.");return true;});player.prepareAsync();}catch(Exception failure){release();message.accept("Could not open the recording. The original is retained.");}}
 void pause(){if(player!=null && !prepared){release();return;}if(player!=null && player.isPlaying())player.pause();handler.removeCallbacks(tick);playing(false);}
 private void stop(){if(player!=null && !prepared){release();return;}if(player!=null && prepared){player.pause();player.seekTo(0);}handler.removeCallbacks(tick);progress.setProgress(0);showTime(0);playing(false);}
 void release(){handler.removeCallbacks(tick);if(player!=null){player.release();player=null;}prepared=false;play.setEnabled(true);progress.setEnabled(false);progress.setProgress(0);showTime(0);playing(false);}
 void dispose(){disposed=true;release();}
 @Override protected void onDetachedFromWindow(){dispose();super.onDetachedFromWindow();}
}
